recipes.code:
{
  "inputs": [
    {
      "id": "faqai-api-key",
      "type": "promptString",
      "description": "FAQai API key (requires a paid plan). Create one at https://faqai.app/settings/api-keys",
      "password": true
    }
  ],
  "servers": {
    "server": {
      "type": "stdio",
      "command": "npx",
      "args": [
        "-y",
        "@faqai/mcp-server@0.5.1"
      ],
      "env": {
        "FAQAI_API_KEY": "${input:faqai-api-key}",
        "FAQAI_BASE_URL": "<faqai-base-url>"
      }
    }
  }
}
